// ═══ WRONG: thenApply with async function → NESTED! ═══
CompletableFuture<CompletableFuture<Integer>> nested =
    CompletableFuture.supplyAsync(() -> "SAV2001")
        .thenApply(id -> fetchBalanceAsync(id));  // returns CF<Integer>!
// thenApply wraps the CF<Integer> in another CF → CF<CF<Integer>>!
// To get the value: nested.get().get() — TWO unwraps! UGLY!

// ═══ CORRECT: thenCompose flattens → single CF! ═══
CompletableFuture<Integer> flat =
    CompletableFuture.supplyAsync(() -> "SAV2001")
        .thenCompose(id -> fetchBalanceAsync(id));  // returns CF<Integer>
// thenCompose FLATTENS: CF<CF<Integer>> → CF<Integer>!
// flat.get() → Integer. ONE unwrap. CLEAN!

// ═══ ANALOGY: Stream map vs flatMap ═══
// map:     Stream<String> → map(s -> List.of(s)) → Stream<List<String>> (nested!)
// flatMap: Stream<String> → flatMap(s -> List.of(s).stream()) → Stream<String> (flat!)
// thenApply  = map     (wraps result as-is)
// thenCompose = flatMap (unwraps inner CF)

// ═══ DECISION RULE ═══
// Function returns T (plain value)?          → thenApply
// Function returns CompletableFuture<T>?     → thenCompose

cf.thenApply(s -> s.toUpperCase());             // String → String: thenApply (Recommended) 
cf.thenApply(s -> Integer.parseInt(s));          // String → Integer: thenApply (Recommended) 
cf.thenCompose(id -> fetchFromDbAsync(id));      // String → CF<Data>: thenCompose (Recommended) 
// cf.thenApply(id -> fetchFromDbAsync(id));     // String → CF<Data>: CF<CF<Data>>! (Avoid) 
