package com.bank.compose;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class ComposeVsApplyTest {

    // Simulate async DB lookup
    CompletableFuture<Integer> fetchBalanceAsync(String accountId) {
        return CompletableFuture.supplyAsync(() -> {
            if ("SAV2001".equals(accountId)) return 100000;
            return 0;
        });
    }

    CompletableFuture<String> fetchNameAsync(String accountId) {
        return CompletableFuture.supplyAsync(() ->
            "SAV2001".equals(accountId) ? "Rajesh" : "Unknown");
    }

    // ═══ WRONG: thenApply with async function → nested CF! ═══
    @Test
    void thenApply_withAsyncFn_producesNestedCF() throws Exception {
        CompletableFuture<CompletableFuture<Integer>> nested =
            CompletableFuture.supplyAsync(() -> "SAV2001")
                .thenApply(id -> fetchBalanceAsync(id));  // CF inside CF!

        // Must unwrap TWICE:
        Integer balance = nested.get().get();
        assertThat(balance).isEqualTo(100000);
        // nested.get() → CF<Integer>. .get() again → Integer. UGLY!
    }

    // ═══ CORRECT: thenCompose flattens → single CF! ═══
    @Test
    void thenCompose_flattens() throws Exception {
        CompletableFuture<Integer> flat =
            CompletableFuture.supplyAsync(() -> "SAV2001")
                .thenCompose(id -> fetchBalanceAsync(id));  // FLAT!

        Integer balance = flat.get();  // ONE unwrap!
        assertThat(balance).isEqualTo(100000);
    }

    // ═══ Chaining multiple async steps — all thenCompose ═══
    @Test
    void chainedCompose_cleanPipeline() throws Exception {
        String result = CompletableFuture
            .supplyAsync(() -> "SAV2001")                         // CF<String>
            .thenCompose(id -> fetchNameAsync(id))                 // CF<String> (flat!)
            .thenCompose(name -> CompletableFuture.supplyAsync(
                () -> "Hello, " + name + "!"))                     // CF<String> (flat!)
            .thenApply(String::toUpperCase)                        // plain transform
            .get();

        assertThat(result).isEqualTo("HELLO, RAJESH!");
    }

    // ═══ thenApply for plain transforms — correct usage ═══
    @Test
    void thenApply_forPlainTransform() throws Exception {
        String result = CompletableFuture
            .supplyAsync(() -> "100000")
            .thenApply(Integer::parseInt)          // String → Integer (plain)
            .thenApply(bal -> bal * 2)              // Integer → Integer (plain)
            .thenApply(bal -> "Balance: " + bal)    // Integer → String (plain)
            .get();

        assertThat(result).isEqualTo("Balance: 200000");
    }
}
